import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { calc } from "../lib/calc.mjs";

test("arithmetic", () => {
  assert.equal(calc("2+3*4"), 14);
});

test("spaces are ignored", () => {
  assert.equal(calc(" 2 + 3 * 4 "), 14);
});

test("parentheses override precedence", () => {
  assert.equal(calc("(2+3)*4"), 20);
  assert.equal(calc("2*(3+(4-1))"), 12);
});

test("subtraction is left-associative", () => {
  assert.equal(calc("10-4-3"), 3);
});

test("division returns the true quotient", () => {
  assert.equal(calc("7/2"), 3.5);
});

test("unary minus is supported", () => {
  assert.equal(calc("-(2+3)*4"), -20);
});

test("invalid input throws", () => {
  assert.throws(() => calc("2+"));
  assert.throws(() => calc("foo"));
  assert.throws(() => calc("(2+3"));
  assert.throws(() => calc("2 3"));
});

test("implementation contains no dynamic code execution APIs", () => {
  const calcPath = path.join(
    path.dirname(fileURLToPath(import.meta.url)),
    "../lib/calc.mjs"
  );
  const source = readFileSync(calcPath, "utf8");
  assert.ok(!source.includes("eval"));
  assert.ok(!source.includes("Function"));
});
